def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    # Extend the diagonal line defined by this adjacent pair.
                    rr, cc = r, c
                    while 0 <= rr - dr < h and 0 <= cc - dc < w:
                        rr, cc = rr - dr, cc - dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] == bg:
                            out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out
